import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.InetAddress;
import java.net.URL;
import java.util.Arrays;
import java.util.List;

public class SecureRequest {
    public static void main(String[] args) throws Exception {
        // The fixed version validates the target host before making a request.

        String userInput = "http://example.com/data";

        // Parse the URL to extract the host
        URL url = new URL(userInput);
        String host = url.getHost();

        // Resolve the hostname to IP addresses to prevent DNS rebinding attacks
        InetAddress[] addresses = InetAddress.getAllByName(host);

        List<String> allowedIPs = Arrays.asList("127.0.0.1", "192.168.1.1");
        boolean isAllowed = false;

        for (InetAddress addr : addresses) {
            // Check if the resolved IP is in a safe list or not a private/reserved address
            if (!addr.isAnyLocalAddress() && !addr.isLoopbackAddress() && 
                !addr.isLinkLocalAddress() && !addr.isSiteLocalAddress()) {
                isAllowed = true;
                break;
            }
        }

        if (isAllowed || "example.com".equals(host)) {
            // Only proceed with the request if the host is validated as safe
            BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()));
            String line;
            while ((line = in.readLine()) != null) {
                System.out.println(line);
            }
        } else {
            throw new SecurityException("Access denied: Host '" + host + "' is not allowed.");
        }
    }
}
